package com.autoops.command.repository;import com.autoops.command.entity.CommandDefinition;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;public interface CommandDefinitionRepository extends JpaRepository<CommandDefinition,Long>{List<CommandDefinition> findByStatusOrderByNameAsc(String status);@Query(value="SELECT * FROM command_definitions WHERE status='APPROVED' AND embedding IS NOT NULL ORDER BY embedding <=> CAST(:embedding AS vector) LIMIT :limit",nativeQuery=true)List<CommandDefinition> semantic(@Param("embedding")String embedding,@Param("limit")int limit);}
